function clone(node):
    if node is null: return null
    map = empty map
    return dfs(node, map)

function dfs(node, map):
    if node in map: return map[node]
    clone = new Node(node.val)
    map[node] = clone
    for each neighbor of node:
        clone.neighbors.add(dfs(neighbor, map))
    return clone
